import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sub, length, float, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CylinderGeometry,
    Color,
    Box3,
    Vector3,
    DirectionalLight,
    PointLight,
  } = THREE;

  const root = new Group();
  root.name = 'orbit-product-hero';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const cBackground = new Color(colors.background ?? '#0b0b10');
  const cSurface = new Color(colors.surface ?? '#14141a');
  const cInk = new Color(colors.ink ?? '#16161d');
  const cPaper = colors.paper ?? '#e8ecf2';
  const cAccent = new Color(colors.accent ?? '#ff2a38');
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ------------------------------------------------------------------
  // BACKDROP PLANE — 7x6 at z=-2.5, engineered vertical gradient
  // ------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const g0 = new Color(gradientStops[0]?.hex ?? '#0b0b10');
    const g1 = new Color(gradientStops[1]?.hex ?? '#101017');
    const g2 = new Color(gradientStops[2]?.hex ?? '#16161d');
    const stop0 = float(gradientStops[0]?.at ?? 0.0);
    const stop1 = float(gradientStops[1]?.at ?? 0.55);
    const stop2 = float(gradientStops[2]?.at ?? 1.0);
    const v = uv().y;
    const c0 = vec3(g0.r, g0.g, g0.b);
    const c1 = vec3(g1.r, g1.g, g1.b);
    const c2 = vec3(g2.r, g2.g, g2.b);
    const lower = mix(c0, c1, smoothstep(stop0, stop1, v));
    const full = mix(lower, c2, smoothstep(stop1, stop2, v));
    // faint centered vignette lift so the stage never reads as flat void
    const centerDist = length(uv().sub(0.5));
    const vignette = oneMinus(smoothstep(float(0.2), float(0.75), centerDist)).mul(0.045);
    backdropMat.colorNode = full.add(vec3(vignette, vignette, vignette.mul(1.15)));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ------------------------------------------------------------------
  // LIGHTS — node-local rim/accent (scene provides ambient 0.6 + key 1.2)
  // Accent rim grazing the left case flank
  // ------------------------------------------------------------------
  const accentRim = new DirectionalLight(cAccent.getHex(), 1.2);
  accentRim.position.set(-3.2, 0.6, -1.2);
  accentRim.target.position.set(0, 0, 0);
  root.add(accentRim);
  root.add(accentRim.target);

  const coolBackRim = new DirectionalLight(0xe8ecf2, 0.7);
  coolBackRim.position.set(2.4, 2.2, -2.0);
  coolBackRim.target.position.set(0, 0, 0);
  root.add(coolBackRim);
  root.add(coolBackRim.target);

  const accentKick = new PointLight(cAccent.getHex(), 0.5, 6.0, 2.0);
  accentKick.position.set(-1.9, -0.6, 1.0);
  root.add(accentKick);

  // ------------------------------------------------------------------
  // PLINTH — low cylinder, radius 1.4, height 0.25, top face at y=-1.1
  // ------------------------------------------------------------------
  const plinthGeo = new CylinderGeometry(1.4, 1.44, 0.25, 64, 1);
  const plinthMat = new MeshStandardNodeMaterial({
    color: cSurface.getHex(),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.1 - 0.125, 0);
  root.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // thin accent reveal ring on the plinth top edge (subtle, <10% frame)
  const ringGeo = new CylinderGeometry(1.41, 1.41, 0.012, 64, 1, true);
  const ringMat = new MeshBasicNodeMaterial();
  ringMat.colorNode = vec3(cAccent.r, cAccent.g, cAccent.b).mul(1.4);
  const ring = new Mesh(ringGeo, ringMat);
  ring.position.set(0, -1.104, 0);
  root.add(ring);
  disposables.push(ringGeo, ringMat);

  // ------------------------------------------------------------------
  // CONTACT SHADOW — radial gradient plane radius 1.6, opacity 0.55
  // ------------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const falloff = oneMinus(smoothstep(float(0.15), float(1.0), d));
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = falloff.mul(0.55);
  }
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.348, 0);
  root.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ------------------------------------------------------------------
  // WATCH MESH GROUP — the hero, normalized to 2.2 units tall
  // ------------------------------------------------------------------
  const watchGroup = new Group();
  watchGroup.name = 'watch-hero';
  root.add(watchGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;
    const model = gltf.scene;

    // normalize to 2.2 scene units tall, centered at origin
    const box = new Box3().setFromObject(model);
    const size = new Vector3();
    box.getSize(size);
    const height = size.y || 1;
    const s = 2.2 / height;
    model.scale.setScalar(s);

    const box2 = new Box3().setFromObject(model);
    const center = new Vector3();
    box2.getCenter(center);
    model.position.sub(center);

    // brushed-metal PBR grade per spec
    model.traverse((child) => {
      if (child.isMesh) {
        const src = child.material || {};
        const mat = new MeshPhysicalNodeMaterial({
          color: src.color ? src.color.getHex() : 0xb8bcc4,
          roughness: 0.52,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4,
        });
        if (src.map) mat.map = src.map;
        if (src.normalMap) mat.normalMap = src.normalMap;
        if (src.roughnessMap) mat.roughnessMap = src.roughnessMap;
        if (src.metalnessMap) mat.metalnessMap = src.metalnessMap;
        if (mat.anisotropy !== undefined) {
          mat.anisotropy = 0.8;
          mat.anisotropyRotation = Math.PI / 2;
        }
        mat.needsUpdate = true;
        child.material = mat;
        disposables.push(mat);
      }
    });

    watchGroup.add(model);

    // entrance: rise-in + weighted-settle
    watchGroup.position.y = -0.35;
    watchGroup.scale.setScalar(0.96);
    const tl = gsap.timeline();
    tl.to(watchGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' });
    tl.to(
      watchGroup.scale,
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' },
      0.2
    );
    tl.to(
      watchGroup.scale,
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      0.55
    );
    timelines.push(tl);
  });

  // ------------------------------------------------------------------
  // TEXT — verbatim spec copy via fontAtlas
  // headline baseline 1.5 units below scene center; caption 0.5 below headline
  // ------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.6);
  root.add(textGroup);

  let headlineObj = null;
  let bodyObj = null;
  let captionObj = null;

  for (const item of items) {
    const role = item.role ?? 'body';
    const text = String(item.text ?? '');
    if (role === 'headline') {
      headlineObj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: cPaper,
        align: 'center',
      });
      headlineObj.position.set(0, -1.5, 0);
      textGroup.add(headlineObj);
    } else if (role === 'body') {
      bodyObj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 26,
        color: cPaper,
        align: 'center',
      });
      bodyObj.position.set(0, -1.85, 0);
      textGroup.add(bodyObj);
    } else if (role === 'caption') {
      captionObj = ctx.fontAtlas.createText(text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: colors.accent ?? '#ff2a38',
        align: 'center',
        letterSpacingPx: 1.5,
      });
      captionObj.position.set(0, -2.15, 0);
      textGroup.add(captionObj);
    }
  }

  // text fade-up entrance
  {
    const tl = gsap.timeline({ delay: 0.25 });
    const targets = [headlineObj, bodyObj, captionObj].filter(Boolean);
    targets.forEach((obj, i) => {
      const finalY = obj.position.y;
      obj.position.y = finalY - 0.2;
      tl.to(obj.position, { y: finalY, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
    timelines.push(tl);
  }

  // ------------------------------------------------------------------
  // CINEMATIC PRIMITIVES — apply every one from config
  // ------------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const handle = fn(watchGroup, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ------------------------------------------------------------------
  // HANDLERS — hover release weighted settle
  // ------------------------------------------------------------------
  root.userData.handlers = {
    pointerout: () => {
      const tl = gsap.timeline();
      tl.to(watchGroup.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.2,
        ease: 'power2.out',
      });
      tl.to(watchGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
  };

  // ------------------------------------------------------------------
  // CLEANUP
  // ------------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    timelines.length = 0;
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    primitiveHandles.length = 0;
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    disposables.length = 0;
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry && typeof child.geometry.dispose === 'function') {
          child.geometry.dispose();
        }
      }
    });
  };

  return root;
}
